CREATE OR REPLACE FUNCTION public.admin_tenant_accounts_page(_search text DEFAULT '',_filter text DEFAULT 'all',_sort text DEFAULT 'created_at',_ascending boolean DEFAULT false,_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ WITH source AS (SELECT to_jsonb(t) r FROM public.admin_list_tenant_accounts() t), filtered AS (SELECT r FROM source WHERE (_search='' OR lower(r::text) LIKE '%'||lower(_search)||'%') AND CASE _filter WHEN 'with_units' THEN (r->>'units_count')::numeric>0 WHEN 'no_units' THEN (r->>'units_count')::numeric=0 WHEN 'unpaid' THEN (r->>'unpaid_invoices')::numeric>0 OR (r->>'paid_amount')::numeric<(r->>'total_price')::numeric WHEN 'fully_paid' THEN (r->>'total_price')::numeric>0 AND (r->>'paid_amount')::numeric>=(r->>'total_price')::numeric WHEN 'has_login' THEN (r->>'has_login')::boolean WHEN 'no_login' THEN NOT (r->>'has_login')::boolean ELSE true END), ordered AS (SELECT r FROM filtered ORDER BY CASE WHEN _ascending THEN r->>CASE WHEN _sort IN ('full_name','created_at','phone') THEN _sort ELSE 'created_at' END END ASC NULLS LAST,CASE WHEN NOT _ascending THEN r->>CASE WHEN _sort IN ('full_name','created_at','phone') THEN _sort ELSE 'created_at' END END DESC NULLS LAST,r->>'id' LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(r) FROM ordered),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)); $$;
REVOKE ALL ON FUNCTION public.admin_tenant_accounts_page(text,text,text,boolean,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_tenant_accounts_page(text,text,text,boolean,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_tenant_accounts_page(text,text,text,boolean,integer,integer)') IS NOT NULL AS tenant_page_ready;